// ---- D-HOST-1: the build that is RUNNING, not the one on disk -------------
//
// `omarchy plugin update` fetches, fast-forwards and calls
// `omarchy-shell shell rescanPlugins`, which is a hot reload rather than a
// restart. This plugin sets `keepLoaded: true`, and what that keeps across a
// reload is the SERVICE: measured on the 0.13.5-to-0.13.6 update
// (2026-10-12, D-REL-6), the host's `rescanPlugins` rebuilt the overlay and
// the bar from the CACHED old components (its `Qt.clearComponentCache` is
// guarded on `typeof ... === "function"`, false on Quickshell 0.3.1), so a
// stale build shows until a restart. An earlier version of this comment said
// the overlay survives a reload; only the service does. So the files on disk
// update and the running interface does not, with nothing to tell the user.
//
// That is not a hypothetical: the 0.7.3 update landed at 14:58 inside a boot
// that had started two days earlier, and the shell rendered the pre-update
// Guide.qml for the rest of that boot's life. It cost a day of contrast work,
// because a verification pass measured a component the shell had never loaded
// (F-CAL-3, F-CAL-4). A user gets the quieter version of the same thing: they
// update, and keep the old interface.
//
// This constant travels WITH the loaded QML. The version in manifest.json
// travels with the directory. When they disagree, the running build is stale.
// The release gate proves the two agree when a version is cut (dev branch), so
// a disagreement at RUNTIME can only mean a reload that did not re-instantiate.
//
// D-REL-16 (2026-11-25): and a disagreement at the service's FIRST reading of
// the manifest means a load that raced an update, which a restart may not
// clear (Qt's disk cache can keep the mix). Every runtime file now carries a
// build stamp of its own (BUILD_FILES below), and buildVerdict, further down,
// reads both: "restart" for the first case, "cache" for the second and for
// files of two builds loaded side by side. D-HOST-16: the manifest is re-read
// at every rescan's hand-off and on its watcher, not only when the guide opens.
var PLUGIN_VERSION = "0.20.0"
// D-REL-16. GENERATED by build_stamps.py (dev branch): --cut rewrites it at
// the cut, and between cuts a new runtime file's row is the one hand edit.
// Every other runtime file, in load order, and the stamp it carries: the
// version of the last cut that changed it. This part's own is PLUGIN_VERSION.
var BUILD_FILES = {
  "BarWidget.qml": "0.20.0",
  "Guide.qml": "0.20.0",
  "Service.qml": "0.20.0",
  "Model.mjs": "0.20.0",
  "Service-pip.js": "0.20.0",
  "Service-player.js": "0.20.0",
  "Service-rewind.js": "0.20.0",
  "Service-sources.js": "0.20.0",
  "model/text.mjs": "0.20.0",
  "model/channels.mjs": "0.20.0",
  "model/browse.mjs": "0.20.0",
  "model/state.mjs": "0.20.0",
  "model/settings.mjs": "0.20.0",
  "model/logos.mjs": "0.20.0",
  "model/player.mjs": "0.20.0",
  "model/mpv.mjs": "0.20.0",
  "model/rewind.mjs": "0.20.0",
  "model/pip.mjs": "0.20.0",
  "model/privacy.mjs": "0.20.0",
  "model/epg.mjs": "0.20.0",
  "model/contrast.mjs": "0.20.0",
  "model/view.mjs": "0.20.0",
  "model/sources.mjs": "0.20.0",
  "model/source-records.mjs": "0.20.0",
  "model/form-edit.mjs": "0.20.0"
}

// Both arguments are strings; anything unparseable answers false, because a
// notice nobody can act on is worse than no notice. Never throws: this runs in
// a QML binding, and a binding that raises leaves the footer undefined.
// Parse the version out of a manifest.json the runtime read from disk. Never
// throws and never returns undefined: this feeds a QML binding, and JSON that
// is mid-write during an update is a normal thing to see, not an error.
function manifestVersion(text) {
  try {
    var m = JSON.parse(str(text))
    return m && typeof m.version === "string" ? m.version : ""
  } catch (e) { return "" }
}

// D-REL-16: an OLDER Service.qml beside this model still calls staleBuild and
// manifestVersion, so both stay exported whatever the reading below becomes.
function staleBuild(loaded, onDisk) {
  var a = str(loaded), b = str(onDisk)
  if (a === "" || b === "") return false
  return a !== b
}

// ---- D-REL-16: is what loaded ONE build, and is it the one on disk --------
//
// A shell that starts while `omarchy plugin update` is writing the plugin can
// compile files of two builds side by side, and Qt's disk cache can keep such
// a unit through every later restart (call (d), measured by the reload rig,
// 2026-11-24). Every runtime file carries its build stamp, a literal compiled
// into the unit Qt caches (BUILD_FILES above), so the stamps the RUNNING code
// holds name the builds it was compiled from. Compared with the table this
// build carries, they say whether what loaded is one build; compared with the
// manifest, whether that build is the one on disk. The names and the fields
// below are frozen, additive only (ARCHITECTURE.md (dev branch) section 9):
// an older build's code reads them beside a newer one in exactly the mix they
// exist to catch.

// Every part's stamp, by its file, this part's own as PLUGIN_VERSION. Read in
// a function body, so it is the part that was LOADED that answers (init
// locality: a top-level initializer may not read another part).
function modelBuildStamps() {
  var out = Object.create(null)
  out["model/build.mjs"] = PLUGIN_VERSION
  out["model/text.mjs"] = BUILD_STAMP_TEXT
  out["model/channels.mjs"] = BUILD_STAMP_CHANNELS
  out["model/browse.mjs"] = BUILD_STAMP_BROWSE
  out["model/state.mjs"] = BUILD_STAMP_STATE
  out["model/settings.mjs"] = BUILD_STAMP_SETTINGS
  out["model/logos.mjs"] = BUILD_STAMP_LOGOS
  out["model/player.mjs"] = BUILD_STAMP_PLAYER
  out["model/mpv.mjs"] = BUILD_STAMP_MPV
  out["model/rewind.mjs"] = BUILD_STAMP_REWIND
  out["model/pip.mjs"] = BUILD_STAMP_PIP
  out["model/privacy.mjs"] = BUILD_STAMP_PRIVACY
  out["model/epg.mjs"] = BUILD_STAMP_EPG
  out["model/contrast.mjs"] = BUILD_STAMP_CONTRAST
  out["model/view.mjs"] = BUILD_STAMP_VIEW
  out["model/sources.mjs"] = BUILD_STAMP_SOURCES
  out["model/source-records.mjs"] = BUILD_STAMP_SOURCE_RECORDS
  out["model/form-edit.mjs"] = BUILD_STAMP_FORM_EDIT
  return out
}

var BUILD_REPORT_FILE_MAX = 64
var BUILD_REPORT_STAMP_MAX = 32

// The stamps a file in `map` names, as a new object without a prototype (so
// a file called `__proto__` is a file, not the object's prototype). Only
// strings are kept, and each is bounded: a report is a file name and a
// version, nothing a view could grow.
function buildStampsCopy(map) {
  var out = Object.create(null)
  if (!map || typeof map !== "object") return out
  for (var k in map) {
    if (!Object.prototype.hasOwnProperty.call(map, k)) continue
    var v = map[k]
    if (typeof v !== "string" || v === "" || k === "" || k.length > BUILD_REPORT_FILE_MAX || v.length > BUILD_REPORT_STAMP_MAX) continue
    out[k] = v
  }
  return out
}

// What a view's report adds (Service.qml's reportBuildStamp): `map` with the
// view's file at its stamp. Anything that is not a bounded, non-empty string
// pair changes nothing. A copy every time, so a binding over it notices, and
// a second report of the same pair reads the same.
function withReportedStamp(map, file, stamp) {
  var out = buildStampsCopy(map)
  if (typeof file === "string" && file !== "" && file.length <= BUILD_REPORT_FILE_MAX &&
      typeof stamp === "string" && stamp !== "" && stamp.length <= BUILD_REPORT_STAMP_MAX) out[file] = stamp
  return out
}

// The row the loaded table holds for `file`: build.mjs's own is
// PLUGIN_VERSION; a file the table does not list has none (null).
function buildRowOf(file) {
  if (file === "model/build.mjs") return PLUGIN_VERSION
  return Object.prototype.hasOwnProperty.call(BUILD_FILES, file) ? BUILD_FILES[file] : null
}

// The verdict. Input (every field optional):
//   own         the service's own stamps: Service.qml, each code-behind
//               through its forwarder, Model.mjs ("?" for a read that threw)
//   reported    what the guide and the bar reported (withReportedStamp)
//   loadedDisk  manifest.json's version at this service's FIRST successful
//               read, "" before one
//   onDisk      manifest.json's version at its LATEST read, "" unknown
// Output: { notice, running, onDisk, loadedDisk, mixed, stamps }.
//   stamps  every stamp counted: `own`, then the model's (modelBuildStamps),
//           then `reported`; "" is not a stamp (a view that has not
//           reported), and a file already counted keeps its first stamp
//   mixed   every counted file whose stamp is not the loaded table's row for
//           it, or that the table does not list ("?" is never a row)
//   notice  "cache"   a mix: files of two builds are loaded -- or the build
//                     was already behind the disk at this service's first
//                     read, which only a load that raced an update gives
//           "restart" the loaded build is whole and older than the disk,
//                     and was not at the first read: an update landed under
//                     a running shell (D-HOST-1)
//           ""        nothing to say, an unknown disk included
// The LATEST reading is asked first: a whole new build whose first read
// caught the old manifest (written last) reads "" once the next read lands.
// Never throws: it feeds a QML binding.
function buildVerdict(input) {
  var o = input && typeof input === "object" ? input : {}
  var stamps = Object.create(null)
  var sources = [buildStampsCopy(o.own), modelBuildStamps(), buildStampsCopy(o.reported)]
  for (var s = 0; s < sources.length; s++) {
    for (var f in sources[s]) if (!Object.prototype.hasOwnProperty.call(stamps, f)) stamps[f] = sources[s][f]
  }
  var mixed = []
  for (var file in stamps) {
    var row = buildRowOf(file)
    if (row === null || stamps[file] !== row) mixed.push(file)
  }
  var running = PLUGIN_VERSION
  var onDisk = typeof o.onDisk === "string" ? o.onDisk : ""
  var loadedDisk = typeof o.loadedDisk === "string" ? o.loadedDisk : ""
  var notice = ""
  if (mixed.length > 0) notice = "cache"
  else if (onDisk !== "" && onDisk !== running) notice = loadedDisk === running ? "restart" : "cache"
  return { notice: notice, running: running, onDisk: onDisk, loadedDisk: loadedDisk, mixed: mixed, stamps: stamps }
}

// The notice a VIEW reads off the service it was handed. "" with no service
// (the no-service surfaces speak then); "cache" for a service with no string
// `buildNotice` -- one from before the stamps, which only a mixed load puts
// beside a stamped view; else the service's own notice.
function serviceBuildNotice(s) {
  if (!s || typeof s !== "object") return ""
  var n = s.buildNotice
  return typeof n === "string" ? n : "cache"
}

